    <div id="app"></div>

    <script>
      const formState = {
        values: {
          fullName: "",
          email: "",
          phone: ""
        },
        touched: {
          fullName: false,
          email: false,
          phone: false
        }
      };

      const validators = {
        fullName(value) {
          if (!value.trim()) {
            return "Full name is required.";
          }

          return "";
        },
        email(value) {
          if (!value.trim()) {
            return "Email address is required.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return "Enter a valid email address.";
          }

          return "";
        },
        phone(value) {
          if (!value.trim()) {
            return "";
          }

          const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
          if (!phonePattern.test(value.trim())) {
            return "Enter a valid phone number using digits, spaces, parentheses, or hyphens.";
          }

          return "";
        }
      };

      function escapeHtml(value) {
        return value
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;");
      }

      function FormField(config) {
        const errorMessage = validators[config.name](formState.values[config.name]);
        const showError = formState.touched[config.name] && Boolean(errorMessage);
        const describedByIds = [];

        if (config.helperText) {
          describedByIds.push(config.name + "-helper");
        }

        describedByIds.push(config.name + "-error");

        return `
          <div class="form-field${showError ? " field-invalid" : ""}">
            <label for="${config.name}">${config.label}${config.required ? ' <span aria-hidden="true">*</span>' : ""}</label>
            <input
              id="${config.name}"
              name="${config.name}"
              type="${config.type}"
              inputmode="${config.inputMode || "text"}"
              placeholder="${config.placeholder}"
              value="${escapeHtml(formState.values[config.name])}"
              aria-required="${config.required ? "true" : "false"}"
              aria-invalid="${showError ? "true" : "false"}"
              aria-describedby="${describedByIds.join(" ")}"
              autocomplete="${config.autoComplete}"
            />
            ${config.helperText ? `<div class="helper-text" id="${config.name}-helper">${config.helperText}</div>` : ""}
            <div class="error-text" id="${config.name}-error" aria-live="polite">${showError ? errorMessage : ""}</div>
          </div>
        `;
      }

      function SupportForm() {
        return `
          <form id="support-form" novalidate>
            ${FormField({
              name: "fullName",
              label: "Full name",
              type: "text",
              placeholder: "Jordan Lee",
              autoComplete: "name",
              required: true
            })}
            ${FormField({
              name: "email",
              label: "Email address",
              type: "email",
              inputMode: "email",
              placeholder: "jordan@example.com",
              autoComplete: "email",
              required: true
            })}
            ${FormField({
              name: "phone",
              label: "Phone number",
              type: "tel",
              inputMode: "tel",
              placeholder: "+1 (555) 123-4567",
              autoComplete: "tel",
              helperText: "Optional. Use a format like +1 (555) 123-4567.",
              required: false
            })}
            <div class="submit-row">
              <button type="submit">Submit request</button>
              <div class="success-text" id="form-success" aria-live="polite"></div>
            </div>
          </form>
        `;
      }

      function SupportPage() {
        return `
          <main class="page-shell">
            <section class="support-card" aria-labelledby="support-heading">
              <div class="support-copy">
                <div class="eyebrow">Support team</div>
                <h1 id="support-heading">Get help from product specialists.</h1>
                <p>
                  Reach out with account questions, onboarding needs, or product issues and
                  we will route your request to the right team.
                </p>
                <ul class="highlights" aria-label="Support highlights">
                  <li>
                    <strong>Fast routing</strong>
                    <span>Requests are triaged with the details you share here.</span>
                  </li>
                  <li>
                    <strong>Clear follow-up</strong>
                    <span>We will reply using the email address you provide.</span>
                  </li>
                </ul>
              </div>
              <div class="form-panel">
                <h2>Contact support</h2>
                <p class="intro">
                  Fill out the form below and our team will be in touch soon.
                </p>
                ${SupportForm()}
              </div>
            </section>
          </main>
        `;
      }

      function setValue(name, value) {
        formState.values[name] = value;
      }

      function setTouched(name) {
        formState.touched[name] = true;
      }

      function validateForm() {
        return Object.keys(validators).every(function (fieldName) {
          return validators[fieldName](formState.values[fieldName]) === "";
        });
      }

      function getErrorMessage(fieldName) {
        return validators[fieldName](formState.values[fieldName]);
      }

      function updateFieldUI(fieldName) {
        const input = document.getElementById(fieldName);
        const field = input.closest(".form-field");
        const errorText = document.getElementById(fieldName + "-error");
        const errorMessage = getErrorMessage(fieldName);
        const showError = formState.touched[fieldName] && Boolean(errorMessage);

        input.setAttribute("aria-invalid", showError ? "true" : "false");
        errorText.textContent = showError ? errorMessage : "";
        field.classList.toggle("field-invalid", showError);
      }

      function updateFormUI() {
        Object.keys(validators).forEach(function (fieldName) {
          updateFieldUI(fieldName);
        });
      }

      function clearSuccessMessage() {
        document.getElementById("form-success").textContent = "";
      }

      function bindEvents() {
        const form = document.getElementById("support-form");

        ["fullName", "email", "phone"].forEach(function (fieldName) {
          const input = document.getElementById(fieldName);

          input.addEventListener("input", function (event) {
            setValue(fieldName, event.target.value);
            if (formState.touched[fieldName]) {
              updateFieldUI(fieldName);
            }
            clearSuccessMessage();
          });

          input.addEventListener("blur", function (event) {
            setValue(fieldName, event.target.value);
            setTouched(fieldName);
            updateFieldUI(fieldName);
          });
        });

        form.addEventListener("submit", function (event) {
          event.preventDefault();

          Object.keys(formState.touched).forEach(function (fieldName) {
            formState.touched[fieldName] = true;
          });

          updateFormUI();

          if (!validateForm()) {
            clearSuccessMessage();
            return;
          }

          document.getElementById("form-success").textContent = "Thanks. Your support request is ready to send.";
        });
      }

      document.getElementById("app").innerHTML = SupportPage();
      bindEvents();
    </script>
