     <title>Support Contact</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f4f7fb;
         --panel: rgba(255, 255, 255, 0.92);
         --panel-border: rgba(148, 163, 184, 0.22);
         --text: #0f172a;
         --muted: #475569;
         --accent: #2563eb;
         --accent-strong: #1d4ed8;
         --error: #b91c1c;
         --error-bg: rgba(248, 113, 113, 0.08);
         --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
         --radius: 24px;
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top left, rgba(37, 99, 235, 0.16), transparent 28%),
           radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.16), transparent 26%),
           var(--bg);
         color: var(--text);
       }

       .page-shell {
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 32px 20px;
       }

       .support-card {
         width: min(100%, 1040px);
         display: grid;
         grid-template-columns: minmax(280px, 1.1fr) minmax(320px, 0.9fr);
         overflow: hidden;
         border: 1px solid var(--panel-border);
         border-radius: var(--radius);
         background: var(--panel);
         box-shadow: var(--shadow);
         backdrop-filter: blur(18px);
       }

       .support-copy {
         padding: 56px;
         background:
           linear-gradient(160deg, rgba(37, 99, 235, 0.98), rgba(30, 64, 175, 0.96)),
           #1d4ed8;
         color: #eff6ff;
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 10px;
         padding: 8px 14px;
         border-radius: 999px;
         background: rgba(255, 255, 255, 0.14);
         color: rgba(239, 246, 255, 0.96);
         font-size: 0.82rem;
         font-weight: 700;
         letter-spacing: 0.04em;
         text-transform: uppercase;
       }

       .support-copy h1 {
         margin: 22px 0 16px;
         font-size: clamp(2rem, 4vw, 3.4rem);
         line-height: 1.04;
       }

