         margin: 0;
         max-width: 34ch;
         font-size: 1.02rem;
         line-height: 1.7;
         color: rgba(239, 246, 255, 0.88);
       }

       .highlights {
         margin: 32px 0 0;
         padding: 0;
         list-style: none;
         display: grid;
         gap: 16px;
       }

       .highlights li {
         padding: 16px 18px;
         border: 1px solid rgba(255, 255, 255, 0.14);
         border-radius: 18px;
         background: rgba(255, 255, 255, 0.08);
       }

       .highlights strong {
         display: block;
         margin-bottom: 6px;
         font-size: 0.96rem;
       }

       .highlights span {
         color: rgba(239, 246, 255, 0.78);
         font-size: 0.95rem;
       }

       .form-panel {
         padding: 56px;
       }

       .form-panel h2 {
         margin: 0 0 10px;
         font-size: 1.6rem;
       }

       .form-panel .intro {
         margin: 0 0 28px;
         color: var(--muted);
         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 18px;
       }

       .form-field {
         display: grid;
         gap: 8px;
       }

       label {
         font-weight: 600;
         font-size: 0.95rem;
       }

       input {
         width: 100%;
         padding: 14px 15px;
         border: 1px solid rgba(148, 163, 184, 0.45);
         border-radius: 14px;
         background: #fff;
         color: var(--text);
         font: inherit;
         transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
       }

       input::placeholder {
         color: #94a3b8;
       }

       input:focus {
         outline: none;
         border-color: rgba(37, 99, 235, 0.7);
         box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
       }

       .helper-text,
       .error-text,
       .success-text {
         font-size: 0.9rem;
         line-height: 1.45;
       }

       .helper-text {
         color: var(--muted);
       }

       .error-text {
         min-height: 1.4em;
         color: var(--error);
       }

       .field-invalid input {
         border-color: rgba(185, 28, 28, 0.62);
         background: var(--error-bg);
       }

       .submit-row {
         margin-top: 10px;
         display: flex;
         align-items: center;
         gap: 14px;
         flex-wrap: wrap;
       }

       button {
         border: 0;
         border-radius: 999px;
         padding: 14px 24px;
         background: linear-gradient(135deg, var(--accent), var(--accent-strong));
         color: #fff;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 18px 30px rgba(37, 99, 235, 0.22);
         transition: transform 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
       }

       button:hover {
         transform: translateY(-1px);
         box-shadow: 0 22px 36px rgba(37, 99, 235, 0.28);
       }

       button:focus-visible {
         outline: 3px solid rgba(37, 99, 235, 0.28);
         outline-offset: 3px;
       }
